using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;
class BackgroundCheck{static void Wait(){var w=Stopwatch.StartNew();while(w.ElapsedMilliseconds<400){Application.DoEvents();System.Threading.Thread.Sleep(10);}}[STAThread]static void Main(){var f=BindingFlags.Instance|BindingFlags.NonPublic;using(var g=new Game()){g.Show();var t=typeof(Game);var c=((System.Collections.Generic.List<Chapter>)t.GetField("chapters",f).GetValue(g)).First(x=>x.id==TavernStory.Id);t.GetField("current",f).SetValue(g,c);t.GetField("index",f).SetValue(g,0);var s=(Save)t.GetField("save",f).GetValue(g);s.sectionAttempts[c.id]=new SectionAttempt{review=true};StoryRoutes.Flag(s,TavernStory.OpeningFlag);StoryRoutes.Flag(s,TavernStory.TransferFlag);t.GetMethod("ShowStory",f).Invoke(g,null);Wait();var content=(Panel)t.GetField("content",f).GetValue(g);t.GetField("index",f).SetValue(g,1);t.GetMethod("UpdateLine",f).Invoke(g,null);if(content.Controls.OfType<WhiteSceneReveal>().Any())throw new Exception("same background should not flash");foreach(int line in new[]{12,1}){t.GetField("index",f).SetValue(g,line);t.GetMethod("UpdateLine",f).Invoke(g,null);var r=content.Controls.OfType<WhiteSceneReveal>().Single();if(r.HoldMs!=100||r.DurationMs!=180)throw new Exception("timing");Wait();if(!r.IsDisposed)throw new Exception("blackout cleanup");}Console.WriteLine("PASS forward/back background blackout, stable same-background dialogue and cleanup");}}}
